from flask import Flask, request, jsonify
from transformers import pipeline

app = Flask(__name__)

# Load the sentiment analysis pipeline from local model cache
print("Loading model from /app/model_cache/sentiment_model...")
model_dir = "/app/model_cache/sentiment_model"
clf = pipeline("text-classification", model=model_dir)
print("Model loaded successfully.")

@app.route("/sentiment", methods=["POST"])
def sentiment():
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Request body must be valid JSON"}), 400

    if not isinstance(data, dict) or "text" not in data:
        return jsonify({"error": "Request body must contain a 'text' field"}), 400

    text = data["text"]
    if not isinstance(text, str):
        return jsonify({"error": "The 'text' field must be a string"}), 400

    if not text.strip():
        return jsonify({"error": "The 'text' field must not be empty"}), 400

    try:
        result = clf(text, top_k=2)[0]
        label = result["label"].lower()
        confidence = {
            "positive": 0.0,
            "negative": 0.0
        }
        for item in clf(text, top_k=2):
            confidence[item["label"].lower()] = round(item["score"], 6)

        return jsonify({
            "sentiment": label,
            "confidence": confidence
        }), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
